"""Explicit run correlation ID used by responses and future Run aggregate (ADR-014/019)."""

from dataclasses import dataclass

from pyllmkit.domain.errors import DomainValidationError


@dataclass(frozen=True, slots=True)
class InferenceRunId:
    """Opaque identity supplied by the caller; never generated by a response."""

    value: str

    def __post_init__(self) -> None:
        if type(self.value) is not str or not self.value.strip():
            raise DomainValidationError("InferenceRunId.value must be a nonblank string")

    def __str__(self) -> str:
        return self.value
